export const SystemStatusSchema = z.object({
  services: z.array(ServiceStateSchema),
  dependencies: z.record(z.string(), DependencyStateSchema),
  resource_guard_level: z.enum(["L0", "L1", "L2", "L3", "L4"]).optional(),
}).strict();
export type SystemStatus = z.infer<typeof SystemStatusSchema>;

export const TaskAcceptSchema = z.object({
  task_id: z.string().uuid(),
  eta_ms: z.number().int().gte(0).nullable().optional(),
}).strict();
export type TaskAccept = z.infer<typeof TaskAcceptSchema>;

export const TaskAssignSchema = z.object({
  task_id: z.string().uuid(),
  kind: z.enum(["analyze", "plan", "monitor", "explain", "compute", "summarize"]),
  title: z.string(),
  input: z.unknown(),
  mission_id: z.string().uuid().nullable().optional(),
  deadline_ms: z.number().int().gte(0),
  priority: z.number().int().gte(0).lte(9),
  /** What "done" means */
  acceptance: z.string(),
}).strict();
export type TaskAssign = z.infer<typeof TaskAssignSchema>;

export const TaskBlockedSchema = z.object({
  task_id: z.string().uuid(),
  needs: z.string(),
  from_role: z.string().nullable().optional(),
}).strict();
export type TaskBlocked = z.infer<typeof TaskBlockedSchema>;

export const TaskCancelSchema = z.object({
  task_id: z.string().uuid(),
  reason: z.string(),
}).strict();
export type TaskCancel = z.infer<typeof TaskCancelSchema>;

export const TaskCompleteSchema = z.object({
  task_id: z.string().uuid(),
  output: z.unknown(),
  summary: z.string(),
  bb_refs: z.array(BBRefSchema),
}).strict();
export type TaskComplete = z.infer<typeof TaskCompleteSchema>;

export const TaskEvaluateSchema = z.object({
  task_id: z.string().uuid(),
  score: z.number().gte(0).lte(1),
  notes: z.string(),
}).strict();
export type TaskEvaluate = z.infer<typeof TaskEvaluateSchema>;

export const TaskFailSchema = z.object({
  task_id: z.string().uuid(),
  reason: z.string(),
  retryable: z.boolean(),
}).strict();
export type TaskFail = z.infer<typeof TaskFailSchema>;

export const TaskProgressSchema = z.object({
  task_id: z.string().uuid(),
  progress: z.number().gte(0).lte(1),
  note: z.string().nullable().optional(),
}).strict();
export type TaskProgress = z.infer<typeof TaskProgressSchema>;

export const TaskRejectSchema = z.object({
  task_id: z.string().uuid(),
  reason: z.enum(["busy", "out_of_scope", "missing_input", "unsafe"]),
  detail: z.string().nullable().optional(),
}).strict();
export type TaskReject = z.infer<typeof TaskRejectSchema>;

export const TaskUpdateDataSchema = z.object({
  task_id: z.string().uuid(),
  state: z.string(),
  assignee_instance_id: z.string().uuid().nullable(),
  title: z.string(),
}).strict();
export type TaskUpdateData = z.infer<typeof TaskUpdateDataSchema>;

export const VelocitySchema = z.object({
  speed_mps: z.number(),
  vertical_mps: z.number().nullable(),
  horizontal_mps: z.number().nullable(),
}).strict();
export type Velocity = z.infer<typeof VelocitySchema>;

export const VehicleSchema = z.object({
  name: z.string().nullable(),
  /** 'rocket', 'truck', ... */
  kind: z.string().nullable(),
  position: PositionSchema.nullable(),
  geo: GeoSchema.nullable(),
  attitude: AttitudeSchema.nullable(),
  velocity: VelocitySchema.nullable(),
  accel_g: z.number().nullable(),
  controls: ControlsSchema.nullable(),
  engine: EngineSchema.nullable(),
  damage: DamageSchema.nullable(),
  /** ksp: pre_launch|flying|sub_orbital|orbiting|escaping|landed|splashed|docked */
  situation: z.string().nullable(),
  stage: StageSchema.nullable(),
  orbit: OrbitSchema.nullable(),
  /** Magnitude of angular velocity in rad/s. Null when the adapter did not read it. */
  angular_rate_rad_s: z.number().nullable().optional(),
  /** Surface-prograde pitch in degrees. Null when velocity is too small to define it. */
  prograde_pitch_deg: z.number().nullable().optional(),
  /** Surface-prograde heading in degrees. Null when velocity is too small to define it. */
  prograde_heading_deg: z.number().nullable().optional(),
}).strict();
export type Vehicle = z.infer<typeof VehicleSchema>;

export const TelemetryFrameSchema = z.object({
  schema: z.literal("titan.telemetry/1"),
  session_id: z.string().uuid(),
  /** 'ksp' | 'ets2' | 'ats' | ... */
  game: z.string(),
  adapter_version: z.string(),
  /** Per session, monotonic */
  seq: z.number().int().gte(0),
  t_mono_ns: z.number().int(),
  t_session_ms: z.number().int(),
  /** KSP UT seconds; SCS game time in seconds */
  t_game_s: z.number().nullable(),
  paused: z.boolean(),
  /** ksp: flight|map|vab|sph|space_center|tracking|menu ; scs: driving|menu|loading|map */
  scene: z.string(),
  domain: z.enum(["space", "ground_vehicle", "aircraft", "naval", "strategy", "other"]),
  vehicle: VehicleSchema,
  resources: z.array(ResourceSchema),
  environment: EnvironmentSchema.nullable(),
  job: JobSchema.nullable(),
  economy: EconomySchema.nullable(),
  /** Adapter-defined, documented in the game package README */
  game_specific: z.record(z.string(), z.unknown()),
}).strict();
export type TelemetryFrame = z.infer<typeof TelemetryFrameSchema>;

/** `TelemetryFrame` without `game_specific`: what the UI receives on the telemetry channel. */
export const TelemetryFrameUISchema = z.object({
  schema: z.literal("titan.telemetry/1"),
  session_id: z.string().uuid(),
  /** 'ksp' | 'ets2' | 'ats' | ... */
  game: z.string(),
  adapter_version: z.string(),
  /** Per session, monotonic */
  seq: z.number().int().gte(0),
  t_mono_ns: z.number().int(),
  t_session_ms: z.number().int(),
  /** KSP UT seconds; SCS game time in seconds */
  t_game_s: z.number().nullable(),
  paused: z.boolean(),
  /** ksp: flight|map|vab|sph|space_center|tracking|menu ; scs: driving|menu|loading|map */
  scene: z.string(),
  domain: z.enum(["space", "ground_vehicle", "aircraft", "naval", "strategy", "other"]),
  vehicle: VehicleSchema,
  resources: z.array(ResourceSchema),
  environment: EnvironmentSchema.nullable(),
  job: JobSchema.nullable(),
  economy: EconomySchema.nullable(),
}).strict();
export type TelemetryFrameUI = z.infer<typeof TelemetryFrameUISchema>;

export const UserSaySchema = z.object({
  text: z.string(),
  to: z.array(z.string()),
}).strict();
export type UserSay = z.infer<typeof UserSaySchema>;

export const UserSayDataSchema = z.object({
  message_id: z.string().uuid(),
  text: z.string(),
  to: z.array(z.string()),
}).strict();
export type UserSayData = z.infer<typeof UserSayDataSchema>;

export const WorldStateTickSchema = z.object({
  bb_version: z.number().int().gte(0),
  scene: z.string(),
  summary: z.unknown(),
}).strict();
export type WorldStateTick = z.infer<typeof WorldStateTickSchema>;

